export const FAQ = [
  ['¿Es gratis? ¿Hay que instalar algo o crear una cuenta?', 'Es gratis, funciona en el navegador y no pide cuenta ni instalación. Conviene Chrome o Edge en una computadora: son los que permiten guardar los proyectos en una carpeta.'],
  ['¿Dónde se guardan mis proyectos?', 'En el navegador de la computadora donde trabajás, de forma automática mientras editás. No se suben a ningún servidor. Para tener una copia fuera del navegador o verlos en otra computadora, elegí una carpeta en el inicio («Guardar los proyectos en una carpeta») o exportá el proyecto como archivo .json desde el menú «Proyecto».'],
  ['¿Puedo perder los proyectos?', 'Sí, si se borran los datos de navegación del sitio o si el navegador libera espacio. Para evitarlo: vinculá una carpeta (mejor dentro de OneDrive, Google Drive o Dropbox), tocá «Pedir al navegador que no los borre» en el inicio y exportá el .json de los proyectos importantes.'],
  ['¿Cómo sigo trabajando en otra computadora?', 'Elegí en las dos la misma carpeta sincronizada (OneDrive, Google Drive o Dropbox para escritorio). Los proyectos aparecen solos. Otra forma: «Proyecto › Exportar el proyecto completo» en una y «Importar proyecto» en la otra.'],
  ['¿Sirve fuera de la Argentina?', 'Sí. Desde la versión 3.5 funciona para toda América Latina, de México a Tierra del Fuego: reconoce el país, usa la proyección UTM de la zona, trae límites administrativos y datos de OpenStreetMap, e incluye un directorio de geoservicios por país.'],
  ['¿Qué archivos propios puedo cargar?', 'Vectores: GeoJSON, KML, KMZ, GPX, CSV con latitud y longitud, y Shapefile (el .zip, o el .shp junto con su .dbf y su .prj). Ráster: GeoTIFF de imágenes procesadas, clasificaciones, índices como NDVI o modelos de elevación, y PNG o JPG con su archivo .pgw, .jgw o .wld. Se eligen en «Capas › Datos propios» o se sueltan sobre el mapa.'],
  ['Cargué un Shapefile y no aparece en su lugar', 'Casi siempre falta el archivo .prj, que es el que dice en qué sistema de coordenadas están los datos. Cargá el .zip completo o el .shp junto con el .dbf y el .prj. Sin .prj, la aplicación supone coordenadas geográficas (latitud y longitud).'],
  ['¿Puedo cargar mi propia clasificación de coberturas?', 'Sí. Soltá el GeoTIFF sobre el mapa y en «Qué contiene» elegí «Clasificación: cada valor es una clase». Después, desde la capa, le ponés nombre y color a cada clase; la leyenda se arma sola. Hay leyendas listas para MapBiomas, ESA WorldCover, Esri y Dynamic World.'],
  ['¿Qué es el NDVI y para qué sirven los índices?', 'El NDVI es un índice de vigor de la vegetación que se calcula con dos bandas de la imagen satelital (infrarrojo cercano y rojo): va de −1 a 1 y es alto donde la vegetación está activa. En «Capas › Imágenes y coberturas › Imagen por fecha» se elige como representación, junto con NDMI (humedad de la vegetación), NDBI (superficie construida) y NBR (áreas quemadas). Si ya calculaste un índice en otro programa, cargalo como GeoTIFF de «valores continuos».'],
  ['Un servicio oficial dice «solo ver» o no carga', 'Algunos servidores no permiten que una página web lea sus datos (les falta el permiso llamado CORS). En ese caso la capa se puede ver como imagen pero no restilizar, y no sale en la exportación. Otros simplemente están caídos ese día. El punto de color al lado de cada organismo indica en qué estado estaba la última vez que se comprobó.'],
  ['¿Cómo agrego la IDE de mi provincia o de mi país si no está en la lista?', 'En «Capas › Servicios oficiales», abajo a la izquierda, pegá la dirección del servicio (WFS, WMS o ArcGIS REST) y tocá «Abrir». La dirección suele figurar en el geoportal del organismo como «servicios» o «geoservicios».'],
  ['¿Qué proyección tengo que usar?', 'Para un municipio, una cuenca o una provincia, la que propone la aplicación: UTM de la zona (o la faja POSGAR 2007 en la Argentina). Para un país grande o el continente, una Lambert acimutal equivalente, que conserva las superficies. Evitá Mercator web para figuras de tesis: agranda las superficies hacia los polos. El capítulo «Fundamentos cartográficos» lo explica.'],
  ['¿A qué resolución exporto?', 'Para imprimir, 300 ppp para figuras en color y 600 ppp si la figura combina líneas finas y texto. Para pantalla o proyector, 150 ppp o el tamaño en píxeles del destino. La aplicación ya propone la resolución del destino elegido en «Figura».'],
  ['¿Qué formato me conviene?', 'PNG para Word y presentaciones; TIFF si la revista lo exige; PDF cuando importa el tamaño exacto en milímetros; SVG si vas a retocar la figura por capas en Inkscape o Illustrator; JPEG solo cuando el peso del archivo importa más que la nitidez.'],
  ['¿Puedo abrir la figura en QGIS?', 'Sí. En «Exportar figura», con PNG, JPEG o TIFF, tildá «Sumar el archivo de georreferencia». Guardá los dos archivos juntos, con el mismo nombre: QGIS ubica la imagen en su lugar. Indicale el sistema de coordenadas del mapa (figura en la barra inferior).'],
  ['¿Cómo cito las fuentes del mapa?', 'En «Figura › Epígrafe y fuentes» la aplicación arma el epígrafe con la proyección, el datum y la fuente de cada capa visible, más tu autoría y la licencia. «Copiar epígrafe» lo deja listo para pegar debajo de la figura.'],
  ['¿Cómo hago el mapa de ubicación (el recuadro chico)?', 'En «Figura › Zooms y mapas de ubicación». Si empezaste con «Nuevo proyecto», ya viene armado con el país. El recuadro se mueve arrastrándolo del borde; el interior desplaza su contenido.'],
  ['¿Cómo trabajo sobre un plano antiguo?', 'En la pestaña «Interpretación»: cargá la imagen del plano, georreferenciala marcando puntos que reconozcas en el plano y en el mapa actual, y dibujá encima tu lectura (caminos, deslindes, poblaciones) indicando para cada trazo si está documentado, inferido o es conjetural.'],
  ['¿Qué es un «sitio» y en qué se diferencia de una capa?', 'Los sitios son tus puntos de estudio: los cargás uno por uno, con coordenadas, marcándolos en el mapa o desde un CSV. Tienen nombre, categorías y símbolo propios, y pueden ir en el epígrafe con sus coordenadas. Una capa es un conjunto de datos de una fuente (un servicio, un archivo).'],
  ['¿Puedo cambiarle el color a un solo polígono o a un tramo?', 'Sí. Tocá el objeto en el mapa: en el panel derecho le das relleno, contorno y nombre propios, y queda con su entrada en la leyenda. Con Mayús + clic sumás más objetos; con el botón «Seleccionar» elegís por rectángulo, lazo o atributo.'],
  ['Se ve bien en pantalla pero impreso no se lee', 'En «Figura» elegí el destino real (por ejemplo, «Tesis impresa A4») y mirá los avisos de legibilidad: marcan textos y líneas por debajo del mínimo. «Ajustar al destino» los corrige. En «Ver como…» podés simular la impresión en grises o la fotocopia.'],
  ['¿Cómo deshago un cambio?', 'Ctrl+Z deshace y Ctrl+Mayús+Z rehace; también están las flechas de la barra superior.'],
  ['¿Puedo volver a la versión anterior?', 'Sí. En el inicio, dentro de «Novedades de la versión 3.5», está el enlace «usar la versión anterior (3.4)». Las dos trabajan con los mismos proyectos. Un mapa que use funciones nuevas solo se abre en la 3.5: la anterior avisa y no lo modifica.'],
  ['¿Funciona en el celular?', 'Se puede abrir y mirar, pero está pensada para computadora: armar una figura necesita pantalla grande, mouse y teclado.'],
  ['¿Funciona sin conexión?', 'La aplicación abre, pero las capas que vienen de servidores (mapas base, servicios oficiales, imágenes satelitales) necesitan conexión. Lo que ya quedó guardado dentro del mapa (límites, datos de OpenStreetMap, tus archivos) sigue disponible.'],
  ['¿A quién le aviso si algo falla o si me falta una función?', 'Al autor, por Instagram (@surtectura.s). Sirve contar qué estabas haciendo, en qué lugar del mapa y, si se puede, una captura de pantalla.'],
];

const S = (id, t, h, figs = []) => ({ id, t, h, figs });

export const MANUAL = [
  { t: 'Qué es Mapas-Tesis', intro: 'Una aplicación web gratuita para hacer las figuras cartográficas de una tesis, una investigación, un artículo o una publicación.', s: [
    S('que-es', 'Para qué sirve', `<p>Mapas-Tesis produce <b>figuras</b>: mapas terminados, con su leyenda, su escala, su norte, su grilla de coordenadas y su epígrafe con fuentes, listos para pegar en un documento, proyectar o imprimir. No reemplaza a un sistema de información geográfica como QGIS: resuelve el tramo final, que es donde más tiempo se pierde, y varias tareas previas que suelen frenar a quien no es especialista (encontrar los datos oficiales, elegir la proyección, citar las fuentes).</p>
<p>Reúne en un solo lugar:</p><ul><li>geoservicios oficiales de la Argentina y de América Latina, límites administrativos y datos de OpenStreetMap;</li><li>imágenes satelitales por fecha (Sentinel-2 y Landsat) y coberturas del suelo;</li><li>tus propios datos: Shapefile, GeoJSON, KML, GPX, CSV, GeoTIFF y clasificaciones;</li><li>herramientas de análisis espacial básicas;</li><li>un espacio para interpretar planos y mapas históricos;</li><li>una mesa de composición pensada para el destino real de la figura.</li></ul>`, [['mapa1', 'Un mapa de localización hecho con capas descargadas para el área.', 'par'], ['clasif', 'El mismo mapa con una clasificación de coberturas propia.', 'par']]),
    S('organizacion', 'Proyectos, mapas y guardado', `<p>El trabajo se organiza en <b>proyectos</b>. Un proyecto corresponde a un trabajo (una tesis, un artículo) y contiene sus datos generales (título, autoría, institución, licencia) y uno o varios <b>mapas</b>. Cada mapa es una figura.</p>
<p>Todo se guarda solo, de manera continua, <b>en el navegador de tu computadora</b>. Nada se sube a un servidor: los proyectos son tuyos y no los ve nadie más. La contracara es que dependen de ese navegador. Por eso conviene, desde el primer día, vincular una carpeta (ver «Guardar en una carpeta») o exportar copias.</p>
<p>La aplicación funciona mejor en Chrome o Edge, en una computadora de escritorio o portátil.</p>`),
    S('privacidad', 'Qué datos salen de tu computadora', `<p>Tus proyectos, tus archivos y los planos que cargues no salen de tu computadora. Lo único que viaja por internet son los pedidos de datos a los servidores públicos que uses: mapas base, servicios oficiales, imágenes satelitales, el buscador de lugares y OpenStreetMap. Esos servidores reciben la zona del mapa que estás mirando, como cualquier visor de mapas.</p>`),
  ] },
  { t: 'Empezar', intro: 'El inicio es la planoteca: ahí están los proyectos de esta computadora y las formas de empezar uno.', s: [
    S('inicio', 'La pantalla de inicio', `<p>Al entrar se ven: las novedades de la versión, la tarjeta <b>Nuevo proyecto</b>, las <b>hojas ya encuadradas</b> (mapas en blanco de América Latina, Sudamérica, México y Centroamérica, y la Argentina), y la lista de <b>proyectos en esta computadora</b>, cada uno con la miniatura de su primer mapa.</p>
<p>Arriba a la derecha están <b>Ayuda</b> e <b>Importar proyecto</b>, que abre un archivo .json exportado desde otra computadora.</p>`, [['inicio', 'El inicio: novedades, formas de empezar y proyectos guardados.', 'ancha']]),
    S('nuevo-proyecto', 'Nuevo proyecto: el asistente', `<p>El asistente tiene tres pasos.</p>
<p><b>1. Los datos del proyecto.</b> Nombre (cómo lo vas a reconocer), tipo de trabajo, título, autoría, institución o programa, dirección, año, palabras clave, resumen, período estudiado y licencia de las figuras. Solo el nombre es obligatorio, pero la autoría y la institución son las que firman los epígrafes. En «Institución o programa», si la tesis está en curso, escribí «doctorando/a en…» o «maestrando/a en…»: «Doctorado en…» detrás del nombre se lee como un título ya obtenido.</p>
<p><b>2. El lugar.</b> Sobre una imagen satelital podés buscar por nombre o por coordenadas, <b>elegir un municipio o partido</b> (la aplicación trae su contorno), <b>marcar un punto</b>, o <b>dibujar un rectángulo o un polígono</b>. A la derecha aparece lo que reconoció: el país («Región»), el ancho del área y el marco de referencia, por ejemplo «WGS 84, UTM zona 14N». El nombre del área se usa en el epígrafe y en el mapa de ubicación.</p>
<p><b>3. El primer mapa.</b> Elegís dónde se va a ver la figura (tesis impresa, artículo, proyector) y las <b>capas de partida</b>: límites de primer y segundo orden, ríos, lagos, rutas, ferrocarriles, localidades, áreas protegidas y el modelo de elevación con sombreado. Las capas tildadas se descargan en ese momento y quedan guardadas dentro del mapa.</p>
<p>Al terminar se abre el mapa ya encuadrado, en la proyección adecuada, con un mapa de ubicación en el país.</p>`, [['asistente-datos', 'Paso 1: los datos del proyecto.', 'ancha'], ['wiz-lugar', 'Paso 2: el municipio elegido sobre la imagen satelital. A la derecha, el país y la proyección reconocidos.', 'ancha'], ['wiz-capas', 'Paso 3: las capas de partida.', 'ancha']]),
    S('hojas', 'Hojas en blanco', `<p>Si lo que necesitás es un mapa de escala continental o nacional, partí de una hoja ya encuadrada: trae los países de base y la grilla, en una proyección equivalente. Después sumás capas como en cualquier mapa. Las mismas hojas están en «Tesis › Hojas de partida» para agregar un mapa nuevo a un proyecto abierto.</p>`),
    S('carpeta', 'Guardar los proyectos en una carpeta', `<p>En el inicio, «Elegir carpeta…» vincula una carpeta de tu computadora (Chrome y Edge). Desde ese momento cada proyecto se guarda también ahí como un archivo, con sus imágenes. Si la carpeta está dentro de OneDrive, Google Drive o Dropbox para escritorio, se sincroniza sola: <b>en otra computadora elegís la misma carpeta y aparecen los mismos proyectos</b>.</p>
<p>Si dos computadoras cambian el mismo proyecto sin haberse sincronizado, no se pisa nada: la otra versión queda como un proyecto aparte para que decidas. Lo que borrás va a una subcarpeta «papelera».</p>
<p>El navegador puede pedir de nuevo el permiso sobre la carpeta al volver a entrar: es una medida de seguridad suya.</p>`),
    S('importar-exportar-proyecto', 'Exportar e importar proyectos', `<p>En el menú <b>Proyecto</b> del editor: «Exportar el proyecto completo, con planos (.json)» genera un único archivo con todos los mapas y las imágenes; «Exportar solo este mapa» genera uno más liviano. «Importar un proyecto o un mapa…» (o «Importar proyecto» en el inicio) los vuelve a abrir. Es la forma de mandarle un proyecto a otra persona o de guardar una copia de seguridad.</p>`, [['menu-proyecto', 'El menú Proyecto.', 'media']]),
  ] },
  { t: 'La pantalla de trabajo', intro: 'El editor tiene cuatro zonas: la barra superior, el panel izquierdo con seis pestañas, la hoja en el centro y el panel de edición a la derecha.', s: [
    S('editor', 'Las zonas del editor', `<p><b>Barra superior.</b> De izquierda a derecha: el botón que oculta el panel izquierdo, la marca (vuelve a los proyectos), el proyecto y el mapa abiertos, el nombre del mapa (se puede cambiar), el estado de guardado, el <b>buscador</b> de lugares o coordenadas, la <b>proyección</b>, deshacer y rehacer, <b>Seleccionar</b>, <b>Proyecto</b>, <b>Ayuda</b> y <b>Exportar figura</b>.</p>
<p><b>Panel izquierdo.</b> Seis pestañas: <b>Tesis</b> (datos, lectura del tema, estilos), <b>Capas</b>, <b>Sitios</b>, <b>Análisis</b>, <b>Interpretación</b> y <b>Figura</b>.</p>
<p><b>La hoja.</b> Es la figura a escala: lo que se ve dentro del papel es lo que se exporta. Arrastrando el mapa se encuadra; la rueda acerca y aleja.</p>
<p><b>Panel derecho (Edición).</b> Muestra las opciones del elemento que toques en la hoja: un texto, la leyenda, la flecha de norte, la escala, un zoom, un sitio o un objeto de una capa.</p>
<p><b>Barra inferior.</b> Coordenadas del cursor, escala del mapa a tamaño de impresión, proyección, tamaño de la hoja y el zoom de la vista previa («Ajustar» la centra).</p>`, [['editor', 'El editor: pestañas a la izquierda, la hoja en el centro y el panel de edición a la derecha.', 'ancha']]),
    S('atajos', 'Gestos y atajos', `<ul><li><b>Arrastrar el mapa</b>: encuadra. <b>Rueda</b>: acerca y aleja.</li><li><b>Tocar un elemento</b> de la figura: lo selecciona y abre sus opciones a la derecha.</li><li><b>Arrastrar</b> leyenda, norte, escala, textos o zooms: los mueve por la hoja.</li><li><b>Flechas</b>: desplazan el elemento 0,5 mm; con <b>Mayús</b>, 5 mm.</li><li><b>Supr</b>: borra el elemento seleccionado.</li><li><b>Ctrl+Z</b> deshace; <b>Ctrl+Mayús+Z</b> rehace.</li><li><b>Clic sobre un objeto de una capa</b>: lo elige para darle estilo propio; <b>Mayús + clic</b> suma más.</li><li><b>Esc</b>: cancela la herramienta en uso.</li></ul>`),
    S('buscador', 'Buscar un lugar o unas coordenadas', `<p>El buscador de la barra superior acepta nombres («Pátzcuaro, Michoacán») y coordenadas en grados decimales (<i>-34.44, -59.44</i>) o en grados, minutos y segundos (<i>34°26'S 59°26'O</i>). Elegí un resultado de la lista para llevar el mapa hasta ahí.</p>`),
  ] },
  { t: 'Pestaña Tesis: el tema y el estilo', intro: 'Antes de dibujar, la aplicación propone un lenguaje gráfico acorde al tema y al lugar.', s: [
    S('tesis-datos', 'Datos del proyecto y tema del mapa', `<p>Arriba se ve la ficha del proyecto, con «Editar datos». Debajo, el <b>tema de este mapa</b> (por defecto, el del proyecto), las palabras clave, la disciplina, el período y el lugar.</p>
<p><b>Interpretar tema y lugar</b> lee esos textos y la zona del mapa y devuelve: una <b>lectura del tema</b> (los ejes que reconoce: histórico, hídrico, circulación, urbano, productivo…), una <b>lectura del lugar</b> (región, relieve cuando puede medirlo) y una <b>propuesta</b> de estilo, proyección y capas, con preguntas para revisar que la figura no afirme más de lo que la investigación sostiene. Es una ayuda para empezar: podés aceptar la propuesta, tomar una parte o ignorarla.</p>
<p>Conviene saber que la lectura del lugar tiene más vocabulario para la llanura pampeana, que es donde nació la aplicación; en otras regiones sus sugerencias pueden ser menos precisas.</p>`, [['panel-tesis', 'Pestaña Tesis: ficha del proyecto, tema y lectura.', 'panel']]),
    S('estilos', 'Estilos de tesis', `<p>Un estilo cambia de una vez colores, tipografías, grosores y fondo de todo el mapa. Hay trece:</p>
<ul><li><b>Tinta y papel</b>: papel cálido y tinta parda, para dialogar con fuentes de archivo.</li><li><b>Paisaje pampeano</b>: ocres y verdes apagados, aguas protagonistas.</li><li><b>Hídrico</b>: todo lo que no es agua pasa a grises.</li><li><b>Físico</b>: sombreado e hipsometría ajustados al rango local de alturas.</li><li><b>Urbano y normativo</b>: base gris y colores categóricos para zonas.</li><li><b>Rural y productivo</b>: la trama de campos y caminos como protagonista.</li><li><b>Temático</b>: base neutra para que solo la variable tenga color.</li><li><b>Etnohistórico y conjetural</b>: trazo lleno, guiones o puntos según la certeza.</li><li><b>Ecológico</b>: sitios de muestreo con paleta apta para daltonismo.</li><li><b>Patrimonio</b>: puntos jerarquizados con rótulos.</li><li><b>Redes y circulación</b>: jerarquía de líneas y flechas de recorrido.</li><li><b>Blanco y negro para imprimir</b>: grises y tramas, sin depender del color.</li><li><b>Proyección en sala oscura</b>: fondo oscuro y colores saturados.</li></ul>
<p>Después de aplicar un estilo, cada capa se puede seguir ajustando por separado.</p>`),
    S('modelo-propio', 'Modelo propio de referencia', `<p>Si tenés una figura que te gusta (de un artículo, de otra tesis, un mapa antiguo), cargala en «Modelo propio de referencia»: se superpone a la hoja como un calco para copiar su composición, y se pueden tomar sus colores. La imagen queda solo en tu navegador.</p>`),
  ] },
  { t: 'Capas', intro: 'Una capa es un conjunto de datos de una misma fuente. El mapa es una pila de capas: la de arriba se dibuja encima.', s: [
    S('capas-lista', 'La lista de capas', `<p>Cada capa tiene una casilla para <b>mostrarla u ocultarla</b>, una etiqueta con su tipo (Vector, Teselas, Imagen, Grilla), un control de <b>opacidad</b> y una <b>×</b> para quitarla. <b>Arrastrando</b> una capa se cambia el orden. «Sitios de estudio» es una capa especial que siempre queda arriba.</p>
<p>Como regla: las imágenes y el relieve van abajo; encima los polígonos; después las líneas; arriba los puntos y los rótulos.</p>`, [['panel-capas', 'La lista de capas y, debajo, «Agregar capas».', 'panel'], ['panel-capa-abierta', 'Una capa abierta: relleno, trama, contorno, rótulos, colores por categoría y leyenda.', 'panel']]),
    S('capas-estilo', 'El estilo de una capa', `<p>Tocando el nombre de una capa se abre su editor:</p>
<ul><li><b>Nombre</b>: es el que aparece en la leyenda.</li><li><b>Relleno</b> y su opacidad, para polígonos.</li><li><b>Trama</b>: diagonales, cuadrícula, puntos, ondas, bañado, pastizal, surcos, ladrillo, triángulos… con su color, separación y grosor. Las tramas permiten distinguir superficies sin depender del color: imprescindibles si la tesis se imprime en blanco y negro.</li><li><b>Contorno</b>: color, grosor en puntos y tipo de línea (continua, discontinua, punteada, punto y raya…).</li><li><b>Símbolo</b>, para puntos: forma, tamaño, borde.</li><li><b>Rótulos</b>: el campo que se escribe, tipografía, tamaño, color y halo.</li><li><b>Colores por categoría (atributo)</b>: pinta cada objeto según el valor de un campo, con la paleta elegida; para campos numéricos ofrece clases por cortes naturales, cuantiles, intervalos iguales o desvío estándar.</li><li><b>Filtro</b>: muestra solo los objetos que cumplen una condición sobre sus atributos.</li><li><b>Leyenda</b>: si la capa figura en la leyenda y con qué texto.</li><li><b>Recorte y visibilidad</b>: recortar la capa al área de estudio y decidir si se dibuja también en los zooms.</li></ul>
<p>Según el tipo de capa, algunas opciones no aparecen: una imagen no tiene contorno, una capa de puntos no tiene trama.</p>`),
    S('objetos', 'Estilo propio para un objeto', `<p>Un clic sobre un polígono, una línea o un punto de una capa vectorial lo <b>elige</b>. En el panel derecho aparecen sus atributos, su superficie o longitud y «Estilo propio para este objeto». Al cambiar un valor, lo elegido pasa a ser una <b>característica propia</b>, con nombre y entrada en la leyenda; el resto de la capa conserva su estilo. <b>Mayús + clic</b> suma o quita objetos.</p>`),
    S('seleccionar', 'La herramienta Seleccionar', `<p>El botón <b>Seleccionar</b> de la barra superior abre un panel para elegir muchos objetos de una capa:</p>
<ul><li><b>Cómo</b>: con un clic, un rectángulo, un lazo dibujado a mano o <b>por atributo</b> (igual, contiene, mayor que, «es uno de», «empieza con»; todas las condiciones o alguna).</li><li><b>Al elegir</b>: selección nueva, sumar, quitar o elegir dentro de lo ya elegido.</li><li><b>Acciones</b>: todos, invertir, ninguno, acercar el mapa a lo elegido y <b>copiar a capa nueva</b>, que convierte la selección en una capa independiente.</li></ul>`, [['seleccionar', 'Un país elegido con la herramienta Seleccionar: a la derecha, sus datos y su estilo propio.', 'ancha']]),
    S('servicios', 'Servicios oficiales', `<p>«Capas › Servicios oficiales» abre el directorio de organismos públicos, en tres solapas:</p>
<ul><li><b>Argentina</b>: organismos nacionales (IGN, INA, INDEC, INTA, Ambiente, SEGEMAR, Transporte, SENASA, CONAE, SHN, Energía, Mapa Educativo) y provinciales (ARBA, Estadística de Buenos Aires, IDECOR, CABA, La Pampa, Mendoza, Neuquén, Salta, entre otros).</li><li><b>América Latina</b>: organismos por país, con filtro de país. Entre los comprobados: IGAC y SGC (Colombia), IGM (Ecuador), IDEP y SERNANP (Perú), SICAR, INDE, INPE, FUNAI, ANA y SGB (Brasil), IDEuy, MTOP y MGAP (Uruguay), CIREN, MOP y Ministerio del Medio Ambiente (Chile), IDE-RD (República Dominicana), INEGI (México, solo ver).</li><li><b>Catálogo IDERA</b>: todos los nodos de la Infraestructura de Datos Espaciales de la República Argentina, leído en vivo.</li></ul>
<p>Al elegir un organismo se listan sus capas, con buscador. Hay dos modos: <b>Vectorial (WFS)</b>, que trae los objetos y permite restilizarlos, filtrarlos, elegirlos y exportarlos; e <b>Imagen (WMS)</b>, que muestra la capa con el estilo del servidor. «Solo las que cubren la vista» acota la lista a tu zona.</p>
<p>El punto de color junto a cada organismo indica el resultado de la última comprobación: se puede leer, solo ver o no respondió. Un servidor «solo ver» no autoriza a las páginas web a leer sus datos: la capa se ve, pero no entra en la exportación.</p>
<p><b>Otro servicio.</b> Abajo a la izquierda se pega la dirección de cualquier servicio WFS, WMS o ArcGIS REST del mundo.</p>`, [['svc-latam', 'Servicios oficiales, solapa América Latina.', 'ancha']]),
    S('catastros', 'Catastros', `<p>Dentro de los servicios oficiales hay parcelarios que se pueden cargar como vectores: en la Argentina, Buenos Aires (ARBA: parcelas, manzanas, quintas, chacras y secciones), CABA, Córdoba (IDECOR), La Pampa, Mendoza (ATM), Neuquén y Salta (IDESA); en la región, Brasil (SICAR, catastro ambiental rural), Colombia (IGAC), Uruguay (IDEuy) y Chile (CIREN). Las parcelas son muchas: se leen a escalas de detalle (más grandes que 1:100.000, aproximadamente) y conviene acercar el mapa antes de agregarlas.</p>
<p>El catastro vigente es una buena referencia para comparar con mensuras y planos históricos.</p>`, [['svc-catastro', 'Capas de un catastro provincial.', 'ancha']]),
    S('limites-osm', 'Límites y OpenStreetMap para toda América Latina', `<p>En «Capas › América Latina: límites y datos de OpenStreetMap»:</p>
<p><b>Límites administrativos.</b> Elegís el país y el nivel: primer orden (estados, provincias, departamentos, regiones), segundo orden (municipios, partidos, cantones, comunas) o el contorno del país. «Solo las unidades que tocan la vista» evita traer todo el país. La fuente es geoBoundaries, en versión simplificada para cartografía: <b>no es el límite oficial</b> de cada instituto geográfico; para trabajo de detalle conviene el servicio oficial.</p>
<p><b>OpenStreetMap, por tema.</b> Ríos y canales, arroyos, lagos y embalses, humedales, rutas principales, secundarias y caminos rurales, ferrocarriles, localidades, áreas protegidas, áreas urbanas, bosques y sitios históricos y arqueológicos. «Traer lo que hay en la vista» descarga ese tema para el área que estás mirando; puede tardar hasta un minuto. Son datos de colaboradores voluntarios: la cobertura es despareja y conviene contrastarla con la imagen satelital.</p>
<p>En los dos casos los datos se descargan una vez y <b>quedan dentro del mapa</b> como capas propias.</p>`),
    S('mapas-base', 'Mapas base y capas de la Argentina', `<p><b>Mapas base para toda América Latina</b>: OpenStreetMap, base clara sin rótulos y rótulos sueltos (CARTO), topográfico, lienzo gris y físico mundial (Esri). Para figuras impresas conviene una base clara y silenciosa, o ninguna, y dibujar encima las capas propias.</p>
<p><b>Argentina.</b> Las bases Argenmap del IGN (común, gris, oscuro, topográfico e híbrido de rótulos) y las capas vectoriales del IGN, que se cargan según la vista: departamentos y partidos, límites interprovinciales, localidades, plantas urbanas, ríos, cursos intermitentes, canales, lagunas, bañados, curvas de nivel, puntos acotados, rutas nacionales y provinciales, caminos rurales, huellas, ferrocarril y estaciones, establecimientos educativos, cementerios, edificios religiosos, taperas, ruinas, establecimientos agropecuarios y los índices de cartas topográficas 1:50.000 y 1:100.000.</p>
<p>En el catálogo también están el relieve (modelo de elevación con rampa de colores y sombreado a medida), la batimetría y las referencias geográficas.</p>`),
    S('datos-propios', 'Tus propios datos', `<p>En «Capas › Datos propios», «Elegir archivos», o directamente <b>soltándolos sobre el mapa</b>.</p>
<p><b>Vectores.</b> GeoJSON; KML y KMZ (Google Earth); GPX (GPS); CSV con columnas de latitud y longitud; Shapefile, como .zip o eligiendo juntos el .shp, el .dbf y el .prj. El .prj indica el sistema de coordenadas: sin él, la aplicación supone latitud y longitud.</p>
<p><b>Ráster.</b> GeoTIFF y PNG o JPG con su archivo de georreferencia (.pgw, .jgw o .wld). Al importar un GeoTIFF se abre un cuadro con el tamaño, las bandas y el sistema de coordenadas, y se elige <b>qué contiene</b>:</p>
<ul><li><b>Imagen en color</b>: una composición ya procesada de tres bandas.</li><li><b>Clasificación</b>: cada valor es una clase. Se elige una leyenda de partida (colores automáticos, MapBiomas, ESA WorldCover, Esri o Dynamic World) y después, desde la capa, se le pone nombre y color a cada clase y se ocultan las que no interesan.</li><li><b>Valores continuos</b>: un índice (NDVI, NDWI) o un modelo de elevación, con una rampa de colores o por intervalos.</li></ul>
<p>También se carga el texto de la <b>fuente</b>, que va al epígrafe (por ejemplo, «elaboración propia sobre imagen Sentinel-2»). Las imágenes muy grandes se reducen para poder trabajar en el navegador: para análisis a resolución completa, el lugar sigue siendo QGIS o Earth Engine.</p>`, [['importar', 'Importar un ráster: nombre, contenido, leyenda de partida y fuente.', 'media'], ['editor-clases', 'Una clasificación importada: cada clase con su color, su nombre y su porcentaje.', 'ancha']]),
  ] },
  { t: 'Imágenes satelitales y coberturas', intro: '«Capas › Imágenes y coberturas» reúne cuatro herramientas de teledetección que no requieren descargar nada.', s: [
    S('imagen-fecha', 'Imagen por fecha', `<p>Elegís el sensor: <b>Sentinel-2</b> (10 m de resolución, escenas del último año) o <b>Landsat</b> (30 m, desde 1972). Indicás un rango de fechas, la estación del año y la nubosidad máxima, y «Buscar fechas en la vista» lista las escenas disponibles. «Agregar el mosaico más despejado» arma uno sin elegir fecha.</p>
<p>La <b>representación</b> define qué bandas se combinan:</p>
<ul><li><b>Color natural</b>: como lo vería el ojo.</li><li><b>Infrarrojo color</b>: la vegetación vigorosa en rojo; separa bien cultivos, montes y agua.</li><li><b>Agricultura</b> e <b>infrarrojo de onda corta</b>: destacan humedad del suelo y estados de los cultivos.</li><li><b>Geología</b> y <b>batimétrica</b>: suelos desnudos y aguas someras.</li><li><b>NDVI</b> (vigor de la vegetación), <b>NDMI</b> (humedad de la vegetación), <b>NDBI</b> (superficie construida) y <b>NBR</b> (áreas quemadas).</li></ul>`, [['imagenes', 'Imagen por fecha: sensor, representación, fechas, estación y nubosidad.', 'ancha']]),
    S('mosaicos', 'Mosaicos anuales y cortina', `<p>Los mosaicos anuales de Sentinel-2 sin nubes dan una imagen pareja por año: sirven como base y para comparar años. La <b>cortina</b> superpone dos imágenes y las separa con una línea que se arrastra, para ver el antes y el después en el mismo lugar.</p>`),
    S('cobertura', 'Cobertura del suelo', `<p>La serie anual de cobertura del suelo a 10 m (Impact Observatory, Microsoft y Esri) va de 2017 a 2025. Se elige el año y una paleta, y «Agregar al mapa». Cada clase se puede ocultar o recolorear desde la capa.</p>
<p>«Análisis en la vista» calcula la <b>superficie por clase</b> en el área visible y, eligiendo un segundo año, los <b>cambios entre los dos años</b>: una matriz de transiciones y un mapa de cambios. Son datos globales generados automáticamente: sirven para tendencias generales, no para parcelas individuales.</p>`, [['imagenes-cobertura', 'Cobertura del suelo: año, comparación, paleta y análisis en la vista.', 'ancha']]),
    S('clasificacion', 'Clasificación propia de la vista', `<p>Agrupa los píxeles de la vista según su respuesta espectral (un agrupamiento no supervisado en la cantidad de clases que indiques). Sirve para explorar patrones del paisaje que la cobertura global no distingue. <b>No reemplaza una clasificación supervisada</b> con verdad de campo: las clases que encuentra no tienen nombre hasta que las interpretás.</p>
<p>Si ya hiciste tu clasificación en otro programa, cargala como GeoTIFF (ver «Tus propios datos»).</p>`),
  ] },
  { t: 'Sitios de estudio', intro: 'Los sitios son los puntos de tu trabajo: lugares de muestreo, establecimientos, casos.', s: [
    S('sitios', 'Cargar y editar sitios', `<p>Tres maneras: escribir el <b>nombre y las coordenadas</b> (latitud, longitud; en decimales o en grados, minutos y segundos) y «Agregar sitio»; <b>«Marcar en el mapa»</b> y tocar el punto; o <b>«Importar CSV»</b> con una tabla de nombre, latitud y longitud.</p>
<p>Tocando un sitio en la lista o en el mapa se editan su nombre, sus coordenadas, una nota, su color o sus categorías. En el mapa se arrastran para corregir la posición.</p>
<p>«Proyecto › Descargar sitios» los exporta como CSV o GeoJSON.</p>`, [['panel-sitios', 'Pestaña Sitios: carga, lista y categorías.', 'panel']]),
    S('sitios-categorias', 'Categorías, símbolos y rótulos', `<p><b>Categorías y colores.</b> Cada categoría tiene nombre y color y aparece en la leyenda. La <b>paleta</b> recolorea todas en orden: hay paletas aptas para daltonismo (Okabe–Ito, Paul Tol), para blanco y negro, para proyector, secuenciales (Viridis) y las habituales de publicaciones científicas. Debajo, un diagnóstico avisa si dos colores son difíciles de distinguir. «Colores desde un gráfico» toma los colores de la imagen de un diagrama tuyo, para que el mapa y los gráficos de la tesis hablen el mismo idioma.</p>
<p>Un sitio puede pertenecer a <b>varias categorías</b>: el símbolo se divide en sectores, franjas o anillos.</p>
<p><b>Símbolo.</b> Forma (círculo, cuadrado, triángulo, rombo, estrella…), tamaño, borde y opacidad. El <b>círculo de área</b> dibuja alrededor de cada sitio un círculo translúcido, de tamaño fijo o con un radio real en kilómetros.</p>
<p><b>Rótulos.</b> Mostrar u ocultar los nombres, tipografía, tamaño, color, halo, negrita y cursiva.</p>`),
  ] },
  { t: 'Análisis', intro: 'Herramientas para leer el territorio con números. Cada resultado se agrega como una capa propia.', s: [
    S('analisis', 'Las herramientas', `<ul><li><b>Clasificar una capa por sus valores</b>: ordena un campo numérico en clases y las colorea con una rampa (mapa de coropletas).</li><li><b>Áreas de influencia</b>: anillos a distancias fijas alrededor de puntos, líneas o polígonos.</li><li><b>Densidad de puntos</b>: dónde se concentran, por hexágonos o con una superficie suavizada.</li><li><b>Polígonos de Thiessen</b>: el área más cercana a cada punto que a cualquier otro.</li><li><b>Contar puntos en polígonos</b>: cuántos sitios hay en cada municipio, por ejemplo.</li><li><b>Patrón de puntos</b>: índice del vecino más próximo, que dice si los puntos están agrupados, dispersos o al azar, y la elipse de desvío, que resume hacia dónde se orientan.</li><li><b>Medir distancias y superficies</b>: mediciones geodésicas, que no dependen de la proyección del mapa.</li><li><b>Perfil topográfico</b>: se dibuja un corte y el perfil se agrega a la figura con su exageración vertical calculada y rotulada.</li><li><b>Llamadas sobre el mapa</b>: un texto con una línea fina que señala un punto.</li></ul>`, [['panel-analisis', 'Pestaña Análisis.', 'panel']]),
    S('analisis-cuidado', 'Qué conviene tener en cuenta', `<p>Las áreas de influencia son distancias en línea recta: no consideran caminos ni obstáculos. Los polígonos de Thiessen suponen que el espacio es homogéneo. El índice del vecino más próximo depende mucho del área que se tome como referencia. Un mapa de densidad cambia según el tamaño del hexágono o el radio de suavizado. En todos los casos, declarar el parámetro usado en el epígrafe o en el texto es parte del método.</p>`),
  ] },
  { t: 'Interpretación sobre planos históricos', intro: 'Para dibujar una lectura propia sobre mapas antiguos o hechos por otros, dejando a la vista cuánto se sabe.', s: [
    S('interp-versiones', 'Versiones', `<p>Una <b>versión</b> es una lectura completa: guarda su propia georreferenciación y sus trazos. Se pueden duplicar, crear vacías, fijar y <b>comparar</b> dos entre sí. Cada versión lleva nombre, autoría, fecha y el <b>criterio o hipótesis</b> de esa lectura: sirve para declarar el método y para mostrar cómo cambió la interpretación.</p>`, [['panel-interp', 'Pestaña Interpretación: versiones, planos fuente y dibujo.', 'panel']]),
    S('georef', 'Cargar y georreferenciar un plano', `<p>«Agregar plano o mapa (imagen)» acepta JPG, PNG o WebP: un escaneo, una fotografía tomada en el archivo o la captura de un mapa ajeno. Queda en tu navegador y viaja dentro del proyecto al exportarlo.</p>
<p>Georreferenciar es decirle a la aplicación dónde cae el plano sobre el mapa actual. Se marcan <b>puntos de control</b>: lugares que reconocés en el plano y en el mapa de hoy (una esquina de manzana, un cruce de caminos, la confluencia de dos arroyos, un mojón). Con ellos se calcula una transformación:</p>
<ul><li><b>Helmert</b> (traslación, giro y escala): desde 2 puntos. No deforma el plano; la mejor opción para una mensura bien hecha.</li><li><b>Afín</b>: desde 3 puntos. Admite escalas distintas en cada eje y cizalla; útil cuando el papel se estiró.</li><li><b>Proyectiva</b>: desde 4 puntos. Para la foto de un plano tomada en ángulo.</li><li><b>Lámina delgada</b>: deformación elástica que hace pasar el plano exactamente por todos los puntos. Para croquis sin rigor métrico.</li></ul>
<p>La aplicación muestra el <b>residuo</b> de cada punto (cuánto se aparta del modelo) y el error medio. Un residuo mucho mayor que los demás señala un punto mal marcado o un lugar que cambió. Conviene repartir los puntos por todo el plano y no alinearlos.</p>
<p>Un error chico no prueba que el plano sea exacto: la lámina delgada da error cero por construcción. Cuanto más flexible es la transformación, más se impone el mapa actual sobre el documento.</p>`),
    S('interp-dibujo', 'Dibujar la interpretación', `<p>Se elige <b>qué se dibuja</b> (camino, huella o rastrillada; deslinde; curso de agua; línea de frontera; suerte, estancia o parcela; bañado; población, casco o puesto; posta, pulpería o capilla; toldería o paradero; hito o mojón; flujo o recorrido; zona de transición; lugar percibido o nombrado) y el <b>grado de certeza</b>:</p>
<ul><li><b>Documentada</b>: figura en la fuente. Trazo lleno.</li><li><b>Inferida</b>: se deduce de otras evidencias. Guiones.</li><li><b>Conjetural</b>: hipótesis de quien interpreta. Puntos.</li></ul>
<p>El color y la forma dicen <i>qué es</i>; el trazo dice <i>cuánto se sabe</i>. Tocando un elemento dibujado se editan su nombre, su período, su fuente y su certeza. «Mover vértices» corrige la geometría.</p>
<p>En «Categorías y simbología» se ajustan grosores, decoraciones de línea (borde, doble línea, ferrocarril, peine, dientes, flechas, postes, cruces), tramas de área y símbolos, y se crean categorías nuevas.</p>`),
  ] },
  { t: 'Figura: componer para el destino', intro: 'La misma información necesita figuras distintas según dónde se va a ver.', s: [
    S('destino', 'Destino, calidad y legibilidad', `<p><b>Destino</b> es lo primero que conviene elegir: tesis impresa A4 (página completa o media), artículo a una o dos columnas, lámina A3, póster A1, proyector 16:9 o 4:3, pantalla compartida en videollamada, monitor, web o PDF digital, y redes sociales. Cada destino fija el tamaño de la hoja, la resolución y los <b>mínimos de legibilidad</b>: por ejemplo, para una tesis impresa, texto de al menos 7 pt y líneas de 0,25 pt o más.</p>
<p><b>Legibilidad</b> lista los elementos que quedan por debajo de esos mínimos. «Ajustar al destino» los lleva al mínimo de una vez.</p>
<p><b>Color y simulación.</b> La salida puede ser en color o en escala de grises. «Ver como…» simula en pantalla la impresión en grises, la fotocopia, un proyector en sala iluminada, una videollamada comprimida y los tres tipos de daltonismo. No cambia la figura: muestra cómo la van a ver.</p>`, [['panel-figura', 'Pestaña Figura: destino, legibilidad, color, página y vista.', 'panel'], ['panel-figura-2', 'Más abajo: vista del mapa, elementos, zooms, textos y epígrafe.', 'panel']]),
    S('pagina', 'Página y vista del mapa', `<p><b>Página y tamaño.</b> Formatos predefinidos (caja de texto de tesis A4, columnas de revista, A5, A4, A3, carta, diapositiva) o medidas propias en milímetros; orientación; márgenes para los rótulos de coordenadas; color de fondo y marco.</p>
<p><b>Vista del mapa.</b> La <b>escala</b> se puede escribir (1:N, a tamaño de impresión), igual que la latitud y la longitud del centro y la rotación. «Meridiano hacia arriba» y «Orientar» giran el mapa para que un meridiano quede vertical, o para reproducir la orientación de un plano histórico. Los botones de abajo llevan a encuadres frecuentes.</p>`),
    S('elementos', 'Leyenda, norte, escala y grilla', `<p>En «Elementos» cada uno se muestra u oculta con su casilla y se abre con «Editar» (o tocándolo en la hoja):</p>
<ul><li><b>Leyenda</b>: título, qué entradas se muestran y con qué texto, orden, tipografía, columnas, fondo y borde. Se pueden agregar elementos propios.</li><li><b>Flecha de norte</b>: modelo, tamaño y posición. Acompaña la rotación del mapa.</li><li><b>Escala gráfica</b>: longitud, divisiones, unidades y estilo.</li><li><b>Grilla de coordenadas</b>: intervalo, formato de los rótulos, líneas o solo marcas en el borde.</li></ul>`, [['inspector-leyenda', 'Edición de la leyenda en el panel derecho.', 'panel']]),
    S('zooms', 'Zooms y mapas de ubicación', `<p><b>Agregar zoom de detalle</b> crea un recuadro que amplía una parte del mapa. Un círculo chico sobre el mapa marca qué se amplía: arrastrándolo cambia el área. El borde del recuadro lo mueve por la hoja; el interior desplaza su contenido.</p>
<p>El <b>mapa de ubicación</b> hace lo contrario: muestra el área de estudio dentro de un territorio mayor (el país, el continente). Los proyectos creados con el asistente ya lo traen. Para la Argentina existe además el mapa de ubicación bicontinental del IGN.</p>`),
    S('textos', 'Textos y epígrafe', `<p><b>Textos</b>: título, nombre de mar u océano, región, rótulo suelto, número de figura y fuentes. Se arrastran sobre la hoja y se editan a la derecha.</p>
<p><b>Epígrafe y fuentes.</b> Con el rótulo («Figura 1») y una descripción breve, la aplicación genera el epígrafe completo: proyección y datum, la fuente de cada capa visible, y, si lo tildás, las coordenadas y notas de los sitios y tu autoría con la licencia. «Copiar epígrafe» lo deja en el portapapeles para pegarlo debajo de la figura en el documento.</p>`),
  ] },
  { t: 'Exportar', intro: '«Exportar figura» produce el archivo final.', s: [
    S('exportar', 'Formatos y resolución', `<ul><li><b>PNG</b>: sin pérdida de calidad. El más cómodo para Word, Google Docs y presentaciones.</li><li><b>TIFF</b>: lo exigen muchas revistas.</li><li><b>PDF</b>: conserva el tamaño exacto en milímetros. Con «PDF sin pérdida» pesa más y no comprime.</li><li><b>JPEG</b>: liviano, con una pérdida que se regula con «Calidad». No conviene para líneas finas y texto.</li><li><b>SVG por capas</b>: vectorial, editable en Illustrator o Inkscape.</li></ul>
<p><b>Resolución</b>: 150 ppp (borrador, pantalla), 300 ppp (fotografías e imágenes en color), 600 ppp (figuras que combinan imagen y texto) y 1200 ppp (dibujo lineal). El cuadro muestra el tamaño en milímetros y en píxeles, y recuerda si quedan avisos de legibilidad.</p>
<p>Las capas de servidores que no autorizan la lectura (las «solo ver») no pueden entrar en la exportación: la aplicación lo avisa.</p>`, [['exportar', 'Exportar figura.', 'media']]),
    S('georreferenciada', 'Figura georreferenciada', `<p>Con PNG, JPEG o TIFF se puede tildar «Sumar el archivo de georreferencia» (.pgw, .jgw o .tfw). Es un archivo de texto de seis líneas que dice dónde va cada píxel. Guardado junto a la imagen y con el mismo nombre, permite abrir la figura en QGIS en su lugar, por ejemplo para seguir dibujando encima. Vale cuando el mapa no está rotado, y hay que indicarle a QGIS el sistema de coordenadas del mapa.</p>`),
  ] },
  { t: 'Fundamentos cartográficos', intro: 'Qué significa cada elemento de un mapa y cómo usarlo bien. No hace falta saberlo para usar la aplicación, pero sí para defender la figura.', s: [
    S('c-mapa', 'Un mapa es un argumento', `<p>Un mapa no es una fotografía del territorio: es una selección. Alguien decidió qué mostrar, qué callar, con qué jerarquía y a qué escala. En una tesis, esa selección es parte del argumento y hay que poder justificarla. Tres preguntas ordenan casi todas las decisiones: <b>qué tiene que entender quien mira</b>, <b>en cuánto tiempo</b> (una diapositiva se mira diez segundos; una lámina, minutos) y <b>qué evidencia sostiene lo que se dibuja</b>.</p>`),
    S('c-coordenadas', 'Coordenadas, datum y marco de referencia', `<p>La posición de un lugar se expresa en <b>coordenadas geográficas</b>: latitud (norte o sur del Ecuador) y longitud (este u oeste de Greenwich), en grados. Se escriben en grados decimales (−34,4417) o en grados, minutos y segundos (34°26′30″ S).</p>
<p>Esas coordenadas se refieren a un modelo de la forma de la Tierra, el <b>datum</b> o marco de referencia. Hoy el estándar mundial es <b>WGS 84</b>, el del GPS. Cada país mantiene un marco propio compatible: POSGAR 2007 en la Argentina, SIRGAS en la región. Para la cartografía de una tesis, las diferencias entre ellos son de centímetros y no se notan. Sí se notan con los marcos antiguos: las cartas topográficas argentinas del siglo XX usan <b>Campo Inchauspe</b>, que difiere del actual en decenas de metros hasta unos doscientos. Por eso, al georreferenciar una carta vieja, hay que respetar su marco.</p>`),
    S('c-proyeccion', 'Proyecciones: qué se conserva y qué se deforma', `<p>La Tierra es curva y el papel es plano: toda proyección deforma algo. Lo que se elige es <b>qué conservar</b>:</p>
<ul><li>Las <b>conformes</b> conservan las formas y los ángulos en lo local: Mercator, Gauss-Krüger, UTM. Son las de la cartografía topográfica.</li><li>Las <b>equivalentes</b> conservan las superficies: Lambert acimutal equivalente, Albers. Son las indicadas cuando se comparan áreas o densidades.</li><li>Las <b>equidistantes</b> conservan distancias desde un punto o a lo largo de ciertas líneas.</li></ul>
<p>En la práctica:</p>
<ul><li><b>Un municipio, una cuenca, una provincia</b>: UTM de la zona, o la faja Gauss-Krüger de POSGAR 2007 en la Argentina. La deformación dentro de la zona es despreciable.</li><li><b>Un país extenso o el continente</b>: Lambert acimutal equivalente centrada en el área. Es la que usan las hojas en blanco.</li><li><b>Mercator web</b> (la de los mapas en línea): cómoda en pantalla, pero agranda las superficies al alejarse del Ecuador. En Tierra del Fuego las áreas se ven casi tres veces más grandes que en el Ecuador. No conviene para figuras de escala regional o continental.</li></ul>
<p><b>UTM</b> divide el mundo en 60 zonas de 6° de longitud, numeradas desde el antimeridiano, y distingue hemisferio norte y sur. La aplicación calcula la zona a partir del lugar. <b>Gauss-Krüger</b> es la misma proyección con fajas de 3°: la Argentina usa siete, de oeste a este. Si el área de estudio queda a caballo de dos zonas, se elige la que contiene la mayor parte.</p>
<p>La proyección del mapa se cambia en la barra superior y debe figurar en el epígrafe: la aplicación la incluye.</p>`),
    S('c-escala', 'Escala', `<p>La escala es la relación entre una distancia en el mapa y la misma distancia en el terreno. <b>1:50.000</b> significa que un centímetro del mapa son 500 metros. Cuidado con el vocabulario: escala <b>grande</b> es la de detalle (1:10.000) y escala <b>chica</b> la de conjunto (1:5.000.000), porque se comparan las fracciones.</p>
<p>La <b>escala numérica</b> solo vale si la figura se reproduce al tamaño exacto para el que se hizo. La <b>escala gráfica</b> (la barra) se agranda y se achica junto con la figura, y por eso es la que debe ir siempre en una tesis, un artículo o una diapositiva.</p>
<p>La escala también define <b>qué se puede afirmar</b>. Un dato tomado de una carta 1:500.000 no se vuelve más preciso por ampliarlo. Una imagen con píxeles de 30 m no permite discutir el ancho de un camino. Conviene que la escala de la figura sea coherente con la escala de las fuentes.</p>
<p>En mapas de escala muy chica (un continente), la escala varía según el lugar del mapa: la barra es una referencia aproximada.</p>`),
    S('c-elementos', 'Los elementos de la figura y cuándo van', `<ul><li><b>Grilla de coordenadas</b>: permite ubicar la figura sin depender de nada más. En una tesis conviene siempre; bastan marcas en el borde con pocos rótulos.</li><li><b>Flecha de norte</b>: imprescindible si el mapa está rotado o no tiene grilla. En mapas de escala continental el norte cambia de dirección a lo ancho de la hoja: ahí es mejor la grilla y omitir la flecha.</li><li><b>Escala gráfica</b>: siempre.</li><li><b>Leyenda</b>: solo lo que el lector no puede deducir. No hace falta explicar que lo azul es agua si hay rótulos. El orden de las entradas debería seguir la importancia para el argumento, no el orden de las capas.</li><li><b>Mapa de ubicación</b>: imprescindible cuando el lector puede no conocer el lugar. Una tesis se lee lejos de donde se escribió.</li><li><b>Epígrafe</b>: número de figura, qué muestra, proyección y datum, fuentes con año, autoría de la elaboración. Una figura debería entenderse sola, sin el texto que la rodea.</li></ul>`),
    S('c-variables', 'El lenguaje gráfico: variables visuales', `<p>Cada propiedad gráfica comunica un tipo de diferencia. Usarlas bien es la base de un mapa legible (la formulación clásica es de Jacques Bertin):</p>
<ul><li><b>Tono de color</b> (rojo, verde, azul) y <b>forma</b>: diferencias de <i>clase</i>. Sirven para categorías sin orden: tipos de uso, de establecimiento.</li><li><b>Valor</b> (claro u oscuro): diferencias de <i>orden</i>. Más oscuro se lee como «más».</li><li><b>Tamaño</b>: diferencias de <i>cantidad</i>. Es la única variable que comunica proporciones.</li><li><b>Trama y orientación</b>: categorías, sobre todo cuando no hay color.</li></ul>
<p>Los errores típicos salen de cruzarlas: usar un arcoíris para una variable ordenada (el ojo no ordena los tonos), o tamaños distintos para categorías que no implican cantidad.</p>
<p><b>Jerarquía visual.</b> Lo que sostiene el argumento va en primer plano: más contraste, más saturación, trazo más grueso. La base va apagada. Si todo grita, nada se lee.</p>`),
    S('c-color', 'Color', `<p>Tres familias de paletas, según el dato:</p>
<ul><li><b>Cualitativas</b>: tonos distintos de luminosidad parecida, para categorías. Más de siete u ocho clases ya no se distinguen: conviene agrupar.</li><li><b>Secuenciales</b>: de claro a oscuro, para cantidades ordenadas.</li><li><b>Divergentes</b>: dos tonos que se alejan de un centro neutro, para datos con un punto medio significativo (aumento y disminución, por encima y por debajo de un promedio).</li></ul>
<p>Alrededor de un 8 % de los varones y un 0,5 % de las mujeres tienen alguna forma de daltonismo: la combinación rojo–verde es la más problemática. Las paletas Okabe–Ito, Paul Tol y Viridis fueron diseñadas para eso, y la simulación de «Figura › Ver como…» permite comprobarlo.</p>
<p>Si la tesis se imprime o se fotocopia en blanco y negro, el color desaparece: hay que apoyarse en el valor (claros y oscuros bien separados) y en las tramas.</p>`),
    S('c-clases', 'Clasificar datos numéricos', `<p>Un mapa de coropletas agrupa valores en clases. El método cambia el mapa, a veces por completo:</p>
<ul><li><b>Cortes naturales (Jenks)</b>: busca los saltos de los datos, para que cada clase sea homogénea. Muestra bien la estructura de <i>ese</i> conjunto, pero no permite comparar dos mapas.</li><li><b>Cuantiles</b>: la misma cantidad de unidades en cada clase. Siempre da un mapa equilibrado, aunque puede separar valores casi iguales.</li><li><b>Intervalos iguales</b>: clases del mismo ancho. Fácil de leer y de comparar; con datos muy asimétricos deja clases vacías.</li><li><b>Desvío estándar</b>: muestra cuánto se aparta cada unidad del promedio. Pide una paleta divergente.</li></ul>
<p>Entre cuatro y seis clases suele ser el límite de lo que se distingue. Dos precauciones: las coropletas se hacen con <b>tasas o densidades</b> (habitantes por km², porcentaje), no con cantidades absolutas, porque las unidades grandes parecerían más importantes solo por su tamaño; y el método y la cantidad de clases se declaran.</p>`),
    S('c-generalizacion', 'Generalización y resolución', `<p>A menor escala hay que <b>generalizar</b>: seleccionar, simplificar, agrupar. Un río con todos sus meandros a escala continental es una mancha. Por eso los límites que trae la aplicación para toda América Latina están simplificados: sirven para ubicar, no para medir un deslinde.</p>
<p>En las imágenes, la <b>resolución espacial</b> es el tamaño del píxel en el terreno: 10 m en Sentinel-2, 30 m en Landsat. Un objeto se reconoce cuando ocupa varios píxeles. La resolución <b>temporal</b> es cada cuánto vuelve el satélite, y la <b>espectral</b>, en qué longitudes de onda mide: de ahí salen los índices. El NDVI, por ejemplo, compara el infrarrojo cercano con el rojo: va de −1 a 1 y es alto donde la vegetación está activa.</p>`),
    S('c-fuentes', 'Fuentes, certeza y licencias', `<p>Cada capa tiene una fuente, una fecha y una escala o resolución de origen. Citarlas no es una formalidad: le dice al lector cuánto confiar. Los datos oficiales tienen respaldo institucional pero pueden estar desactualizados; OpenStreetMap suele estar más al día pero su cobertura es despareja; una clasificación automática global acierta en lo general y falla en lo particular.</p>
<p>Un mapa tiende a mostrar todo con la misma seguridad. Cuando parte de lo que se dibuja es inferencia o hipótesis, hay que <b>hacerlo visible</b>: trazo lleno, guiones y puntos, como en la pestaña Interpretación, y decirlo en el epígrafe.</p>
<p><b>Licencias.</b> Los datos de OpenStreetMap exigen atribución (licencia ODbL); geoBoundaries y la mayoría de los datos públicos, también. La aplicación incluye esas atribuciones en el epígrafe. Para tus propias figuras podés elegir una licencia en los datos del proyecto: CC BY 4.0 permite reutilizarlas citándote.</p>`),
    S('c-revision', 'Lista de revisión antes de entregar', `<ul><li>¿La figura se entiende sin leer el texto?</li><li>¿Tiene escala gráfica, coordenadas o norte, y mapa de ubicación si hace falta?</li><li>¿La leyenda explica todo lo que no es obvio, y nada más?</li><li>¿El epígrafe dice proyección, datum, fuentes con año y autoría?</li><li>¿Se lee al tamaño real del destino? ¿Y en grises?</li><li>¿Los colores se distinguen con daltonismo?</li><li>¿Lo conjetural se distingue de lo documentado?</li><li>¿La escala de la figura es coherente con la de las fuentes?</li><li>¿Los topónimos están bien escritos y son los que usa la bibliografía?</li></ul>`),
  ] },
  { t: 'Problemas frecuentes', intro: '', s: [
    S('p-capas', 'Una capa no carga o tarda', `<p>Los servidores públicos a veces están caídos o lentos. Probá más tarde, acercá el mapa (se pide menos información) o buscá la misma capa en otro organismo. Las capas vectoriales grandes (parcelas, caminos rurales) solo se leen a escalas de detalle. OpenStreetMap puede tardar hasta un minuto en áreas grandes: achicar la vista ayuda.</p>`),
    S('p-archivo', 'Mi archivo no se ubica o no abre', `<p>Shapefile fuera de lugar: falta el .prj. CSV que no se reconoce: las columnas deben llamarse de forma reconocible (latitud y longitud, lat y lon, x e y) y usar punto decimal. GeoTIFF que no abre: puede estar en un sistema de coordenadas poco frecuente o ser demasiado grande; exportalo desde QGIS en UTM o en coordenadas geográficas y con compresión.</p>`),
    S('p-proyectos', 'No veo mis proyectos', `<p>Los proyectos viven en un navegador concreto: si cambiaste de navegador, de perfil o de computadora, no están ahí. Tampoco aparecen en una ventana de incógnito. Si los tenías en una carpeta, elegila de nuevo en el inicio. Si exportaste el .json, importalo.</p>`),
    S('p-exportar', 'La exportación sale incompleta o pesada', `<p>Si falta una capa, es de un servidor «solo ver». Si el archivo pesa demasiado, bajá la resolución o usá JPEG. Si el navegador se queda sin memoria con hojas grandes a 600 o 1200 ppp, exportá a 300 ppp o en PDF.</p>`),
    S('p-ayuda', 'Cómo pedir ayuda o proponer mejoras', `<p>Mapas-Tesis la desarrolla el Arq. Juan Patricio Addesso, doctorando en Geografía (Universidad del Salvador), y mejora con lo que cuentan quienes la usan. Para avisar de un error, pedir una función o sumar el servicio de catastro o la IDE de tu provincia o país: escribí por Instagram a <b>@surtectura.s</b>.</p>`),
  ] },
  { t: 'Glosario', intro: '', s: [
    S('glosario', 'Términos', `<p><b>ArcGIS REST</b>: servicio de datos geográficos de servidores Esri. <b>Capa</b>: conjunto de datos de una fuente. <b>Coropleta</b>: mapa que colorea unidades según un valor. <b>CORS</b>: permiso que un servidor da para que una página web lea sus datos. <b>Datum</b>: modelo de referencia de la forma de la Tierra. <b>DEM</b>: modelo digital de elevación. <b>Epígrafe</b>: texto al pie de la figura. <b>GeoJSON, KML, GPX, Shapefile</b>: formatos de datos vectoriales. <b>Georreferenciar</b>: ubicar una imagen en coordenadas reales. <b>GeoTIFF</b>: imagen con sus coordenadas incorporadas. <b>IDE</b>: infraestructura de datos espaciales, el geoportal de un organismo. <b>NDVI</b>: índice de vigor de la vegetación. <b>ppp</b>: píxeles por pulgada. <b>Proyección</b>: forma de llevar la superficie curva de la Tierra al plano. <b>Ráster</b>: datos en grilla de píxeles (imágenes, clasificaciones, elevación). <b>Residuo</b>: diferencia entre un punto de control y el modelo de georreferenciación. <b>UTM</b>: proyección universal transversa de Mercator, en zonas de 6°. <b>Vector</b>: datos hechos de puntos, líneas y polígonos con atributos. <b>WFS</b>: servicio web que entrega vectores. <b>WMS</b>: servicio web que entrega imágenes de mapa.</p>`),
  ] },
];

// ---------- buscador sobre el contenido (sin conexión, sin inteligencia artificial) ----------
const STOP = new Set('a al algo como con cual cuando de del desde donde el ella en entre era es esa ese eso esta este esto estoy ha hace hacer hago hay la las le lo los me mi mis muy no o para pero por porque puedo puede se si sin sobre su sus te tengo tiene tu tus un una uno unas unos y ya que quiero necesito sirve manera forma app aplicacion mapas tesis cosa'.split(' '));
const SYN = {
  guardar: ['guarda', 'guardan', 'guardado', 'carpeta'], guardo: ['guardan', 'carpeta'], borrar: ['borra', 'perder', 'supr', 'quitar'], bajar: ['exportar', 'descargar'], descargar: ['exportar', 'descargan'],
  imprimir: ['impresa', 'impresion', 'ppp'], shp: ['shapefile'], satelite: ['satelital', 'satelitales', 'sentinel', 'landsat'], satelital: ['sentinel', 'landsat'], foto: ['imagen', 'plano'], antiguo: ['historico', 'historicos', 'plano'], viejo: ['historico', 'plano', 'anterior'],
  recuadro: ['ubicacion', 'zoom'], citar: ['epigrafe', 'fuentes', 'cito'], cita: ['epigrafe', 'fuentes'], referencias: ['leyenda'], norte: ['flecha'], color: ['colores', 'paleta', 'relleno'], colores: ['paleta', 'relleno'],
  punto: ['sitio', 'sitios', 'puntos'], puntos: ['sitios'], limite: ['limites'], provincia: ['provincias', 'limites'], municipio: ['municipios', 'partido'], parcela: ['parcelas', 'catastro', 'catastros'], parcelas: ['catastro', 'catastros'],
  resolucion: ['ppp'], dpi: ['ppp', 'resolucion'], word: ['png'], qgis: ['georreferencia', 'georreferenciada'], celular: ['telefono'], telefono: ['celular'], internet: ['conexion'], offline: ['conexion'],
  deshacer: ['deshace', 'deshago'], error: ['falla', 'problema'], idera: ['servicios', 'oficiales'], ide: ['servicios', 'geoportal'], wms: ['servicios'], wfs: ['servicios'], excel: ['csv'], kmz: ['kml'], clasificacion: ['clases', 'coberturas'],
  proyeccion: ['utm', 'posgar'], coordenadas: ['latitud', 'longitud', 'grilla'], compartir: ['exportar', 'json', 'carpeta'], otra: ['otro'], computadora: ['navegador', 'carpeta'], gratis: ['gratuita'], precio: ['gratis'], cuenta: ['registro'],
};
export function normalize(s) { return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/<[^>]+>/g, ' ').replace(/[^a-z0-9ñ]+/g, ' ').trim(); }
function stem(w) { if (w.length > 5) w = w.replace(/(aciones|amiento|imientos|imiento)$/, '').replace(/(mente|ados|adas|idos|idas|ando|iendo)$/, ''); if (w.length > 4) w = w.replace(/(es|os|as|ar|er|ir|an|en)$/, ''); if (w.length > 3) w = w.replace(/[aeos]$/, ''); return w; }
function tokens(s, expand) {
  const out = [];
  for (const w of normalize(s).split(' ')) { if (!w || STOP.has(w) || w.length < 2) continue; out.push(stem(w)); if (expand && SYN[w]) for (const x of SYN[w]) out.push(stem(x)); }
  return out;
}
let INDEX = null;
function buildIndex() {
  const docs = [];
  FAQ.forEach(([q, a], i) => docs.push({ kind: 'faq', id: `faq-${i}`, title: q, html: `<p>${a}</p>`, where: 'Preguntas comunes', boost: 1.35 }));
  MANUAL.forEach((ch, ci) => ch.s.forEach((sec) => docs.push({ kind: 'manual', id: sec.id, title: sec.t, html: sec.h, where: `Manual · ${ci + 1}. ${ch.t}`, boost: 1 })));
  QUICK.forEach(([t, d], i) => docs.push({ kind: 'quick', id: `q-${i}`, title: t, html: `<p>${d}</p>`, where: 'Guía rápida', boost: 0.9 }));
  const df = new Map();
  for (const d of docs) { d.tt = tokens(d.title); d.bt = tokens(d.html); d.tf = new Map(); for (const w of d.bt) d.tf.set(w, (d.tf.get(w) || 0) + 1); for (const w of new Set([...d.tt, ...d.bt])) df.set(w, (df.get(w) || 0) + 1); }
  INDEX = { docs, df, n: docs.length };
}
function snippet(html, qs) {
  const parts = html.replace(/<\/(p|li)>/g, '$&\n').split('\n').map((x) => x.replace(/<[^>]+>/g, '').trim()).filter(Boolean);
  let best = parts[0] || '', bs = -1;
  for (const p of parts) { const ts = new Set(tokens(p)); let s = 0; for (const q of qs) if (ts.has(q)) s++; if (s > bs) { bs = s; best = p; } }
  return best.length > 420 ? `${best.slice(0, 400).replace(/\s\S*$/, '')}…` : best;
}
// Devuelve hasta `max` pasajes del manual que responden a la pregunta
export function searchHelp(question, max = 4) {
  if (!INDEX) buildIndex();
  const qs = [...new Set(tokens(question, true))];
  if (!qs.length) return [];
  const res = [];
  for (const d of INDEX.docs) {
    let s = 0, hits = 0;
    for (const q of qs) {
      const idf = Math.log(1 + INDEX.n / (1 + (INDEX.df.get(q) || 0)));
      const inT = d.tt.includes(q) ? 1 : 0, tf = d.tf.get(q) || 0;
      if (inT || tf) { hits++; s += idf * (inT * 2.6 + Math.min(3, tf) / (1 + d.bt.length / 260)); }
    }
    if (hits) res.push({ doc: d, score: s * d.boost * (0.55 + 0.45 * hits / qs.length) });
  }
  res.sort((a, b) => b.score - a.score);
  const top = res.slice(0, max).filter((r, i) => i === 0 || r.score > res[0].score * 0.38);
  return top.map((r) => ({ id: r.doc.id, kind: r.doc.kind, title: r.doc.title, where: r.doc.where, html: r.doc.html, text: snippet(r.doc.html, qs), score: r.score }));
}
